<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import {useI18n} from 'vue-i18n'
import {api,write,errorMessage} from '../lib/api'
import {time} from '../lib/state'
import type {Rule,AlertEvent,Room,Sensor} from '../lib/types'
import Notice from '../components/Notice.vue'
import Icon from '../components/Icon.vue'
const {t}=useI18n()
const rules=ref<Rule[]>([]),events=ref<AlertEvent[]>([]),rooms=ref<Room[]>([]),sensors=ref<Sensor[]>([]),loading=ref(true),busy=ref(false),error=ref(''),formError=ref(''),tab=ref<'rules'|'events'>('rules'),open=ref(false),editing=ref('')
const form=reactive({name:'',target:'',metric:'temperature' as Rule['metric'],operator:'above' as Rule['operator'],threshold:24,duration:15,reset_threshold:23,enabled:true})
async function load(){error.value='';loading.value=true;try{[rules.value,events.value,rooms.value,sensors.value]=await Promise.all([api<Rule[]>('/alerts/rules'),api<AlertEvent[]>('/alerts/events'),api<Room[]>('/rooms'),api<Sensor[]>('/sensors')])}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
function show(rule?:Rule){editing.value=rule?.id??'';formError.value='';Object.assign(form,rule?{name:rule.name,target:rule.sensor_id?'sensor:'+rule.sensor_id:'room:'+rule.room_id,metric:rule.metric,operator:rule.operator,threshold:rule.threshold,duration:rule.duration_seconds/60,reset_threshold:rule.reset_threshold,enabled:rule.enabled}:{name:'',target:rooms.value[0]?'room:'+rooms.value[0].id:sensors.value[0]?'sensor:'+sensors.value[0].id:'',metric:'temperature',operator:'above',threshold:24,duration:15,reset_threshold:23,enabled:true});open.value=true}
function targetName(rule:Rule){return rule.sensor_id?sensors.value.find(s=>s.id===rule.sensor_id)?.name??rule.sensor_id:rooms.value.find(r=>r.id===rule.room_id)?.name??rule.room_id}
async function save(){formError.value='';if(!form.target||!(form.operator==='above'?form.reset_threshold<form.threshold:form.reset_threshold>form.threshold)){formError.value=t('ruleValidation');return}busy.value=true;const sep=form.target.indexOf(':'),kind=form.target.slice(0,sep),id=form.target.slice(sep+1);try{await write<Rule>('/alerts/rules'+(editing.value?'/'+encodeURIComponent(editing.value):''),{name:form.name,room_id:kind==='room'?id:null,sensor_id:kind==='sensor'?id:null,metric:form.metric,operator:form.operator,threshold:form.threshold,duration_seconds:Math.round(form.duration*60),reset_threshold:form.reset_threshold,enabled:form.enabled},editing.value?'PATCH':'POST');open.value=false;await load()}catch(e){formError.value=errorMessage(e)}finally{busy.value=false}}
async function toggle(rule:Rule){error.value='';try{const updated=await write<Rule>('/alerts/rules/'+encodeURIComponent(rule.id),{enabled:!rule.enabled},'PATCH');rules.value=rules.value.map(r=>r.id===rule.id?updated:r)}catch(e){error.value=errorMessage(e)}}
async function remove(rule:Rule){if(!confirm(t('confirmDelete')+' '+rule.name))return;error.value='';try{await api('/alerts/rules/'+encodeURIComponent(rule.id),{method:'DELETE'});rules.value=rules.value.filter(r=>r.id!==rule.id)}catch(e){error.value=errorMessage(e)}}
onMounted(()=>void load())
</script>
<template>
<main class="page">
<header class="page-header"><div><div class="eyebrow">SENSOGRID / {{ t('alerts') }}</div><h1>{{ t('alerts') }}</h1><p>{{ t('ruleHint') }}</p></div><button class="primary" @click="show()"><Icon name="plus" :size="16" />{{ t('newRule') }}</button></header><div class="workspace-heading"><div class="segmented"><button :class="{active:tab==='rules'}" @click="tab='rules'">{{ t('rules') }} · {{ rules.length }}</button><button :class="{active:tab==='events'}" @click="tab='events'">{{ t('events') }} · {{ events.length }}</button></div><button class="icon-button" :aria-label="t('refresh')" @click="load"><Icon name="refresh" :size="16" /></button></div><Notice v-if="error" kind="error">{{ t('requestFailed') }}<details><summary>{{ t('details') }}</summary>{{ error }}</details></Notice><div v-if="loading" class="skeleton plan" :aria-label="t('loading')"></div><template v-else-if="tab==='rules'"><article v-for="rule in rules" :key="rule.id" class="rule-item"><div><h3>{{ rule.name }}</h3><p>{{ targetName(rule) }} · {{ t(rule.metric==='offline'?'offlineMetric':rule.metric) }} {{ t(rule.operator).toLowerCase() }} {{ rule.threshold }} {{ rule.metric==='humidity'?'%':rule.metric==='offline'?'min':'°C' }} · {{ rule.duration_seconds/60 }} min</p><small>{{ t('resetThreshold') }}: {{ rule.reset_threshold }}</small></div><div class="page-actions"><button :class="{primary:rule.enabled}" :aria-pressed="rule.enabled" :disabled="busy" @click="toggle(rule)">{{ t(rule.enabled?'enabled':'disabled') }}</button><button class="icon-button" :aria-label="t('edit')+' '+rule.name" @click="show(rule)"><Icon name="edit" :size="16" /></button><button class="text-button danger" @click="remove(rule)">{{ t('delete') }}</button></div></article><div v-if="!rules.length" class="empty-state"><Icon name="bell" :size="32" /><h2>{{ t('noRules') }}</h2><button @click="show()">{{ t('newRule') }}</button></div></template><template v-else><article v-for="event in events" :key="event.id" class="event-item"><span class="tag" :class="{warn:event.state==='active'}">{{ t(event.state) }}</span><div><h3>{{ event.rule_name }}</h3><p>{{ event.message }}</p><small v-if="event.resolved_at">{{ t('resolved') }}: {{ time(event.resolved_at) }}</small></div><time>{{ time(event.started_at) }}</time></article><div v-if="!events.length" class="empty-state"><Icon name="check" :size="32" /><h2>{{ t('noEvents') }}</h2></div></template>
<Teleport to="body"><div v-if="open" class="modal-backdrop" @pointerdown.self.prevent @keydown.esc="open=false"><form v-dialog class="modal" role="dialog" aria-modal="true" :aria-label="t(editing?'editRule':'newRule')" @submit.prevent="save"><header class="modal-header"><h2>{{ t(editing?'editRule':'newRule') }}</h2><button type="button" class="icon-button" :aria-label="t('close')" @click="open=false"><Icon name="close" /></button></header><Notice v-if="formError" kind="error">{{ t('requestFailed') }}<details open><summary>{{ t('details') }}</summary>{{ formError }}</details></Notice><div class="form-grid"><label class="full">{{ t('name') }}<input v-model="form.name" required maxlength="100"></label><label class="full">{{ t('target') }}<select v-model="form.target" required><option value="">{{ t('select') }}</option><optgroup :label="t('rooms')"><option v-for="room in rooms" :key="room.id" :value="'room:'+room.id">{{ room.name }}</option></optgroup><optgroup :label="t('sensors')"><option v-for="sensor in sensors" :key="sensor.id" :value="'sensor:'+sensor.id">{{ sensor.name }}</option></optgroup></select></label><label>{{ t('metric') }}<select v-model="form.metric"><option value="temperature">{{ t('temperature') }} (°C)</option><option value="humidity">{{ t('humidity') }} (%)</option><option value="offline">{{ t('offlineMetric') }}</option></select></label><label>{{ t('operator') }}<select v-model="form.operator"><option value="above">{{ t('above') }}</option><option value="below">{{ t('below') }}</option></select></label><label>{{ t(form.metric==='offline'?'offlineThreshold':'threshold') }}<input v-model.number="form.threshold" type="number" step=".1" required></label><label>{{ t('resetThreshold') }}<input v-model.number="form.reset_threshold" type="number" step=".1" required></label><label>{{ t('duration') }}<input v-model.number="form.duration" type="number" min="0" max="10080" step="1" required></label><label class="check"><input v-model="form.enabled" type="checkbox">{{ t('enabled') }}</label></div><p class="helper">{{ t('thresholdHint') }}</p><footer class="modal-footer"><button type="button" @click="open=false">{{ t('cancel') }}</button><button class="primary" :disabled="busy">{{ t(busy?'saving':'save') }}</button></footer></form></div></Teleport>
</main>
</template>
